/**
 * dsh-plugin-projects — browser half.
 *
 * Contributes two seats into the official Web Client composition:
 *  - `shell.overlay`: the auth gate (a full-frame login card while the host
 *    guard is armed and no valid token is stored; unmounts when satisfied)
 *  - `settings.section`: the "Projects & Users" settings page — the admin
 *    console for projects, one-shot users, tokens and workspace sync
 *
 * Follows the harness UI rules: slots registry + locale namespace + CSS
 * Modules with semantic --dsw-alias-* tokens (no theme selectors, no color
 * literals), presentation rules in CSS, React 18 automatic JSX.
 */
import type { ClientContext } from '@deepseek-ai/dsh-client-runtime/client'
// Type-only: pulls the ctx.locale Context merge.
import type {} from '@deepseek-ai/dsh-client-locale/client'
import type { PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import { AuthGateView } from './auth-gate.tsx'
import { AdminSectionView } from './admin-section.tsx'
import { browserDeps } from './api.ts'
import { zh, en } from './locales.ts'

/** Services required by this plugin (slots registry + locale dictionaries). */
export const inject = ['slots', 'locale']

/** Locale-namespace 'projects' dictionary key type re-export for consumers. */
export type { ProjectsLocaleKey } from './locales.ts'

type GateProps = PropsRuntime<'shell.overlay'> & PropsLocale<'projects'>
function AuthGateEntry(props: GateProps): React.ReactElement {
  return <AuthGateView t={props.t} deps={browserDeps} />
}

type AdminProps = PropsRuntime<'settings.section'> & PropsLocale<'projects'>
function AdminSectionEntry(props: AdminProps): React.ReactElement {
  return <AdminSectionView t={props.t} close={props.close} deps={browserDeps} />
}

/**
 * Mount the projects surfaces into the Web Client.
 * @param ctx - client root context.
 */
export function apply(ctx: ClientContext): void {
  ctx.effect(() => ctx.locale.register('projects', { zh, en }), 'projects: dictionaries')

  // Login gate on the frame-wide floating layer (list kind, additive id).
  ctx.slots.inject('shell.overlay', () => ctx.slots.register(
    { name: 'shell.overlay', id: 'projects-auth-gate', order: 0, locale: 'projects' },
    AuthGateEntry,
  ))

  // Admin console as a settings page (nav label follows the active locale).
  ctx.slots.inject('settings.section', () => ctx.slots.register(
    {
      name: 'settings.section',
      id: 'projects-admin',
      order: 200,
      locale: 'projects',
      label: () => ctx.locale.bind('projects')('section.title'),
    },
    AdminSectionEntry,
  ))
}
