/**
 * The shell.overlay auth gate: while the host guard is armed and no valid
 * token is stored, this entry covers the whole frame with a login card. On
 * success it stores the token, notifies authEvents, and unmounts itself out
 * of the way. Fail-open by design (see resolveGate). Uncontrolled form —
 * values are read through FormData at submit time.
 */
import { useEffect, useState, type FormEvent } from 'react'
import {
  ApiError,
  login,
  resolveGate,
  type ClientDeps,
  type GateDecision,
} from './api.ts'
import type { ProjectsLocaleKey } from './locales.ts'
import css from './auth-gate.module.css'

/** Translate function for the projects namespace. */
export type TranslateProjects = (key: ProjectsLocaleKey) => string

/** Props of the testable inner view. */
export interface AuthGateViewProps {
  /** Locale reader (zh/en dictionaries in locales.ts). */
  t: TranslateProjects
  /** Environment (fetch/storage), injectable for tests. */
  deps: ClientDeps
}

/** Sentinel while the initial gate probe is still in flight. */
const PROBING = Symbol('probing')

/** The inner view: probe, render the card, submit, get out of the way. */
export function AuthGateView(props: AuthGateViewProps): React.ReactElement | null {
  const [gate, setGate] = useState<GateDecision | typeof PROBING>(PROBING)
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)

  useEffect(() => {
    let alive = true
    void resolveGate(props.deps.fetch, props.deps.storage).then((decision) => {
      if (alive) setGate(decision)
    })
    return () => { alive = false }
  }, [props.deps])

  if (gate === PROBING || gate.phase === 'open') return null

  const onSubmit = (event: FormEvent<HTMLFormElement>): void => {
    event.preventDefault()
    if (busy) return
    const data = new FormData(event.currentTarget)
    const username = String(data.get('username') ?? '')
    const password = String(data.get('password') ?? '')
    setBusy(true)
    setError('')
    void login(props.deps, username, password)
      .then(() => { setGate({ phase: 'open' }) })
      .catch((err: unknown) => {
        setError(err instanceof ApiError ? err.message : String(err))
      })
      .finally(() => { setBusy(false) })
  }

  const t = props.t
  return (
    <div className={css.veil}>
      <form
        className={css.card}
        aria-label={t('gate.title')}
        onSubmit={onSubmit}
      >
        <h1 className={css.title}>{t('gate.title')}</h1>
        <p className={css.subtitle}>{t('gate.subtitle')}</p>
        <label className={css.label} htmlFor="projects-gate-username">{t('gate.username')}</label>
        <input
          id="projects-gate-username"
          name="username"
          className={css.input}
          type="text"
          autoComplete="username"
        />
        <label className={css.label} htmlFor="projects-gate-password">{t('gate.password')}</label>
        <input
          id="projects-gate-password"
          name="password"
          className={css.input}
          type="password"
          autoComplete="current-password"
        />
        {error ? <p className={css.error} role="status">{error}</p> : null}
        <button className={css.submit} type="submit" disabled={busy}>
          {t(busy ? 'gate.signingIn' : 'gate.submit')}
        </button>
      </form>
    </div>
  )
}
